import math
from typing import List

def gumbel_cdf(x: float) -> float:
    """Standard Gumbel CDF G(x) = exp(-exp(-x))."""
    return math.exp(-math.exp(-x))

def check_max_stability(ns: List[int], xs: List[float]) -> None:
    """Verify the exact identity G(x + log n)^n = G(x)."""
    for n in ns:
        for x in xs:
            lhs = gumbel_cdf(x + math.log(n)) ** n
            rhs = gumbel_cdf(x)
            print(f"n={n:>5} x={x:+.1f}: |G(x+log n)^n - G(x)| = {abs(lhs-rhs):.2e}")

if __name__ == "__main__":
    check_max_stability([2, 10, 100, 1000], [-1.0, 0.0, 1.0])

import math
from typing import List

def gumbel_cdf(x: float) -> float:
    return math.exp(-math.exp(-x))

def exp_max_cdf(x: float, n: int) -> float:
    """CDF of recentered max of n i.i.d. Exp(1): (1 - e^{-x}/n)^n."""
    return (1.0 - math.exp(-x) / n) ** n

def convergence_table(x: float, ns: List[int]) -> None:
    """Show (1 - e^{-x}/n)^n -> G(x) (Fisher-Tippett-Gnedenko)."""
    target = gumbel_cdf(x)
    for n in ns:
        approx = exp_max_cdf(x, n)
        print(f"n={n:>7}: approx={approx:.10f} target={target:.10f} "
              f"err={abs(approx-target):.2e}")

if __name__ == "__main__":
    convergence_table(0.7, [10, 100, 1000, 10000, 100000])

